def build():
    n = dm.nodes()
    direct, rail = dm.links()
    ids = [i for i in n.index]
    lat, lon = n.latitude_deg.values, n.longitude_deg.values
    la, lo = np.radians(lat), np.radians(lon)
    D = 2 * 6371 * np.arcsin(np.sqrt(np.sin((la[:, None] - la[None, :]) / 2) ** 2 +
                                      np.cos(la[:, None]) * np.cos(la[None, :]) * np.sin((lo[:, None] - lo[None, :]) / 2) ** 2))
    k = {x: i for i, x in enumerate(ids)}
    adj = np.zeros((len(ids), len(ids)), bool)
    for a, b in direct:
        if a in k and b in k:
            adj[k[a], k[b]] = adj[k[b], k[a]] = True
    # пересадка — только в узлах перевозчиков (data/assumptions/transfer_hubs.csv): по кратчайшему пути
    # через любой аэропорт слишком много поездок шло через Казань и Новосибирск
    hubs = set(pd.read_csv(ROOT / "data/assumptions/transfer_hubs.csv").iata)
    is_hub = np.array([x in hubs for x in ids])
    pairs, X, route = [], [], []
    for i in range(len(ids)):
        for j in range(i + 1, len(ids)):
            a, b = ids[i], ids[j]
            if D[i, j] < A["min_pair_km"]:
                continue
            f = dm.features(n, a, b, rail)
            if adj[i, j]:
                via = None
            else:
                ok = adj[i] & adj[j] & is_hub
                ok[[i, j]] = False
                if not ok.any():
                    continue
                det = np.where(ok, D[i] + D[j], np.inf)
                h = int(det.argmin())
                if det[h] / D[i, j] > A["od_max_circuity"]:
                    continue
                via = ids[h]
            pairs.append((a, b))
            X.append([f[c] for c in dm.FEATS])
            route.append(via)
    X = np.column_stack([np.ones(len(X)), np.array(X)])
    # матрица «рейс × поездка»: какие поездки идут по рейсу
    links = {}
    for p, ((a, b), via) in enumerate(zip(pairs, route)):
        legs = [(a, b)] if via is None else [(a, via), (via, b)]
        for x, y in legs:
            links.setdefault(frozenset((x, y)), []).append(p)

class Demand:
    """Спрос пары за год (оба направления): известный поток → таблица шага 2 → формула шага 2."""

    def __init__(self):
        self.n = dm.nodes()
        self.direct, self.rail = dm.links()
        fit = json.loads((P / "demand_fit.json").read_text(encoding="utf-8"))
        co = fit["coefficients"]
        self.beta = np.array([co["const"]] + [co[k] for k in dm.FEATS])
        self.f_lo, self.f_hi = fit["cautious_factor"], fit["optimistic_factor"]
        t = pd.read_csv(P / "demand_pairs.csv")
        self.tab = {}
        for r in t.itertuples():
            base = r.observed if pd.notna(r.observed) and r.observed_coverage != "airline_group" else r.pax_base
            v = {"base": float(base), "cautious": float(r.pax_cautious), "method": r.method}
            self.tab[(r.a, r.b)] = self.tab[(r.b, r.a)] = v
        self.cache = {}

    def get(self, a, b, scen):
        if (a, b) in self.tab:
            return self.tab[(a, b)][scen]
        key = (min(a, b), max(a, b))
        if key not in self.cache:
            f = dm.features(self.n, a, b, self.rail)
            self.cache[key] = float(np.exp(dm.predict(self.beta, np.array([[f[k] for k in dm.FEATS]]))[0]))
        v = self.cache[key]
        return v if scen == "base" else v * self.f_lo
